    19|    private const val PREFS_NAME = "vitahero_secure_tokens"
    20|    private const val FALLBACK_PREFS_NAME = "vitahero_tokens_fallback"
    21|    private const val KEY_ACCESS_TOKEN = "access_token"
    22|    private const val KEY_REFRESH_TOKEN = "refresh_token"
    23|    private const val KEY_USER_ID = "user_id"
