    31|        val cached = prefs
    32|        if (cached != null) return cached
    33|
    34|        return synchronized(this) {
    35|            prefs ?: run {
    36|                val result = try {
    37|                    val masterKey = MasterKey.Builder(context)
    38|                        .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
    39|                        .build()
    40|                    EncryptedSharedPreferences.create(
